2	// This module never contacts a remote server or reads the user's SSH config.
3	export function parseRepositoryRemote(value, { authored = false } = {}) {
4	  if (typeof value !== 'string') return null;
5	  const raw = authored ? value : value.trim();
6	  if (!raw || /[\s\\\u0000-\u001f\u007f?#]/.test(raw)) return null;
7	  const scp = raw.match(/^git@([^/:]+):(.+)$/);
8	  const scpAbsolute = Boolean(scp && scp[2].startsWith('/'));
9	  const expanded = scp ? `ssh://git@${scp[1]}/${scp[2].replace(/^\//, '')}` : raw;
10	  const match = expanded.match(/^(https?|ssh):\/\/([^/]+)\/(.+)$/i);
11	  if (!match) return null;
12	  // Validate the original path before URL parsing can collapse dot segments.
13	  let segments;
14	  try {
15	    segments = match[3].replace(/\/$/, '').split('/');
16	    // Git passes SCP paths literally; percent escapes are decoded only in URIs.
17	    if (!scp) segments = segments.map(decodeURIComponent);
18	  }
19	  catch { return null; }
20	  if (segments.some((part) => !part || part === '.' || part === '..' || /[/\\\s\u0000-\u001f\u007f?#]/.test(part))) return null;
21	  let url;
22	  try { url = new URL(expanded); } catch { return null; }
23	  const protocol = url.protocol;
24	  if (protocol === 'ssh:' && (url.username !== 'git' || url.password)) return null;
25	  if (authored && protocol !== 'ssh:' && (url.username || url.password)) return null;
26	  const hostname = url.hostname.toLowerCase();
27	  if (!hostname) return null;
28	  const provider = hostname === 'github.com' ? 'github' : hostname === 'gitee.com' ? 'gitee' : null;
29	  const last = segments.length - 1;
30	  if (provider) segments[last] = segments[last].replace(provider === 'github' ? /\.git$/i : /\.git$/, '');
31	  if (!segments[last] || segments[last] === '.' || segments[last] === '..') return null;
32	  const repositoryPath = segments.join('/');
33	  // Only known forges map HTTPS and SSH to one repository namespace. Other
34	  // hosts retain transport, port and remote-relative/absolute path semantics.
35	  const port = url.port || (protocol === 'ssh:' ? '22' : protocol === 'https:' ? '443' : '80');
36	  const endpoint = provider && ((protocol === 'https:' && port === '443') || (protocol === 'ssh:' && port === '22'))
37	    ? 'standard' : `${protocol}${port}`;
38	  const pathKind = provider ? 'repository' : scp && !scpAbsolute ? 'relative' : 'absolute';
39	  const identityPath = provider === 'github' ? repositoryPath.toLowerCase() : repositoryPath;
40	  const encodedPath = segments.map(encodeURIComponent).join('/');
41	  const canonicalUrl = scp ? `git@${hostname}:${scpAbsolute ? '/' : ''}${repositoryPath}`
42	    : `${protocol}//${protocol === 'ssh:' ? 'git@' : ''}${url.host}/${encodedPath}`;
43	  return { identity: JSON.stringify([hostname, endpoint, pathKind, identityPath]), url: canonicalUrl, provider, protocol, path: repositoryPath, endpoint };
44	}
